import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import { MessageCircle, X, Send, Camera, Mic, Trash2, Upload, Aperture, Sparkles, BrainCircuit, ExternalLink, ChevronRight, Search, Globe, MapPin, Coffee, ArrowRight, CheckCheck } from 'lucide-react';
import { getTravelChatResponse } from '../services/geminiService';
import { ChatMessage, Source } from '../types';
import { SettingsModal } from './Modals';

interface AIChatProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  onOpenSmartPlan: () => void;
}

const STARTER_PROMPTS = [
  { icon: Globe, text: "Best places to visit in October?" },
  { icon: Coffee, text: "Hidden cafes in Paris" },
  { icon: MapPin, text: "3-day itinerary for Tokyo" },
  { icon: Sparkles, text: "Unique honeymoon destinations" },
];

export const AIChat: React.FC<AIChatProps> = ({ isOpen, setIsOpen, onOpenSmartPlan }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | undefined>(undefined);

  // Camera State
  const [showMediaOptions, setShowMediaOptions] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { 
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); 
  }, [messages, loading, selectedImage]);

  // Ensure video stream is attached when the video element mounts
  useEffect(() => {
    if (isCameraOpen && videoRef.current && streamRef.current) {
      videoRef.current.srcObject = streamRef.current;
    }
  }, [isCameraOpen]);

  // Get User Location on Mount
  useEffect(() => {
    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
            (position) => {
                setUserLocation({
                    lat: position.coords.latitude,
                    lng: position.coords.longitude
                });
            },
            (error) => {
                console.log("Location access denied or error:", error);
            }
        );
    }
  }, []);

  // Cleanup camera stream on unmount or when camera closes
  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setShowMediaOptions(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        e.preventDefault();
        const blob = items[i].getAsFile();
        if (blob) {
          const reader = new FileReader();
          reader.onloadend = () => {
            setSelectedImage(reader.result as string);
          };
          reader.readAsDataURL(blob);
        }
        break;
      }
    }
  };

  const startCamera = async () => {
    try {
      setShowMediaOptions(false);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      streamRef.current = stream;
      setIsCameraOpen(true);
    } catch (err) {
      console.error("Error accessing camera:", err);
      setShowSettings(true); // Show settings on permission failure
      setIsCameraOpen(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setIsCameraOpen(false);
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        setSelectedImage(dataUrl);
        stopCamera();
      }
    }
  };

  const handleVoiceInput = () => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.interimResults = false;
      recognition.maxAlternatives = 1;

      recognition.onstart = () => setIsListening(true);

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(prev => prev ? `${prev} ${transcript}` : transcript);
        setIsListening(false);
      };

      recognition.onerror = (event: any) => {
          setIsListening(false);
          if (event.error === 'not-allowed' || event.error === 'permission-denied') {
              setShowSettings(true);
          }
      };
      recognition.onend = () => setIsListening(false);

      try {
          recognition.start();
      } catch(e) {
          console.error("Speech recognition error", e);
      }
    } else {
      alert("Voice input is not supported in this browser.");
    }
  };

  const handleSend = async (textOverride?: string) => {
    const userMsgText = typeof textOverride === 'string' ? textOverride : input;
    const userImage = selectedImage;

    if ((!userMsgText.trim() && !userImage) || loading) return;

    setMessages(prev => [...prev, { 
      role: 'user', 
      text: userMsgText,
      image: userImage || undefined,
      timestamp: Date.now()
    }]);

    setInput('');
    setSelectedImage(null);
    setLoading(true);

    try {
      const history = messages.slice(-10);
      // Pass userLocation to the service
      const result = await getTravelChatResponse(history, userMsgText || "What is this?", userImage || undefined, userLocation);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: result.text,
        sources: result.sources,
        relatedQuestions: result.relatedQuestions,
        timestamp: Date.now()
      }]);
    } catch (error) { 
      setMessages(prev => [...prev, { role: 'model', text: "Connection error. Please try again.", timestamp: Date.now() }]); 
    } finally { 
      setLoading(false); 
    }
  };

  const handleSmartPlanClick = () => {
      onOpenSmartPlan();
  };

  const isMapSource = (uri: string) => {
    return uri.includes('maps.google.com') || uri.includes('google.com/maps');
  };

  if (!isOpen) return (
    <div className="fixed bottom-20 right-4 md:bottom-8 md:right-8 flex flex-col gap-3 items-end z-50">
      <button 
        onClick={handleSmartPlanClick}
        className="group flex items-center gap-1.5 bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 pl-3 pr-1 py-1 rounded-full shadow-lg border border-indigo-100 dark:border-slate-700 transition-all hover:scale-105 hover:shadow-xl"
      >
        <span className="font-bold text-xs tracking-wide group-hover:text-indigo-700 dark:group-hover:text-indigo-300">AI</span>
        <div className="w-6 h-6 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-full flex items-center justify-center text-white shadow-inner">
           <Sparkles size={12} className="animate-pulse" />
        </div>
      </button>

      <button 
        onClick={() => setIsOpen(true)} 
        className="bg-blue-600 hover:bg-blue-700 text-white p-3 rounded-full shadow-xl transition-transform hover:scale-110"
      >
        <MessageCircle size={22} />
      </button>
    </div>
  );

  return (
    <>
    <div className="fixed bottom-20 right-4 md:bottom-8 md:right-8 w-full max-w-[90vw] md:w-[450px] h-[600px] bg-white dark:bg-slate-900 rounded-2xl shadow-2xl z-50 flex flex-col border border-gray-200 dark:border-slate-700 overflow-hidden animate-fade-in-up">

      {/* Live Camera Overlay */}
      {isCameraOpen && (
        <div className="absolute inset-0 z-50 bg-black flex flex-col">
           <div className="absolute top-4 right-4 z-10">
              <button onClick={stopCamera} className="p-2 bg-black/50 text-white rounded-full hover:bg-black/70"><X size={24} /></button>
           </div>
           <div className="flex-1 relative flex items-center justify-center overflow-hidden">
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
           </div>
           <div className="h-24 bg-black/80 flex items-center justify-center">
              <button 
                onClick={capturePhoto}
                className="w-16 h-16 rounded-full border-4 border-white flex items-center justify-center hover:bg-white/20 transition-colors"
              >
                 <div className="w-12 h-12 bg-white rounded-full" />
              </button>
           </div>
        </div>
      )}

      {/* Header */}
      <div className="bg-white dark:bg-slate-900 border-b border-gray-100 dark:border-slate-800 p-4 flex justify-between items-center shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="bg-gradient-to-br from-indigo-500 to-blue-600 p-1.5 rounded-lg shadow-sm">
             <BrainCircuit size={18} className="text-white" />
          </div>
          <div>
            <h3 className="font-bold text-slate-800 dark:text-white leading-none text-sm">Pro Assistant</h3>
            <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-0.5">Powered by Go Pro AI</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={handleSmartPlanClick} className="text-xs bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-300 px-2 py-1 rounded font-medium hover:bg-indigo-100 dark:hover:bg-indigo-900/50 transition-colors">
                Plan Trip
            </button>
            <button onClick={() => setIsOpen(false)} className="hover:bg-gray-100 dark:hover:bg-slate-800 p-1.5 rounded-full transition-colors text-gray-500"><X size={20} /></button>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 bg-white dark:bg-slate-900 scrollbar-thin scrollbar-thumb-gray-200 dark:scrollbar-thumb-slate-700">

        {messages.length === 0 && (
           <div className="h-full flex flex-col items-center justify-center opacity-0 animate-fade-in" style={{ animationDelay: '0.1s', animationFillMode: 'forwards' }}>
              <div className="w-16 h-16 bg-blue-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
                 <Search size={32} className="text-blue-500 opacity-80" />
              </div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Where to next?</h3>
              <p className="text-gray-500 text-sm text-center max-w-[250px] mb-8">Ask about real-time events, hidden gems, or weather.</p>

              <div className="grid grid-cols-1 gap-3 w-full max-w-[300px]">
                 {STARTER_PROMPTS.map((p, i) => (
                    <button 
                      key={i} 
                      onClick={() => handleSend(p.text)}
                      className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-slate-800 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-xl border border-gray-100 dark:border-slate-700 transition-all text-left group"
                    >
                       <div className="bg-white dark:bg-slate-700 p-1.5 rounded-lg text-gray-400 group-hover:text-blue-500 transition-colors shadow-sm">
                          <p.icon size={16} />
                       </div>
                       <span className="text-sm text-gray-700 dark:text-gray-200 font-medium">{p.text}</span>
                       <ChevronRight size={14} className="ml-auto text-gray-300 group-hover:text-blue-500" />
                    </button>
                 ))}
              </div>
           </div>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`flex flex-col mb-6 animate-fade-in-up ${m.role === 'user' ? 'items-end' : 'items-start'}`}>

            {/* User Message */}
            {m.role === 'user' && (
               <div className="bg-gray-100 dark:bg-slate-800 px-4 py-2.5 rounded-2xl rounded-br-none max-w-[85%] text-slate-800 dark:text-slate-200 text-sm shadow-sm border border-transparent dark:border-slate-700">
                  {m.image && (
                    <div className="mb-2 rounded-lg overflow-hidden border border-gray-200 dark:border-slate-700">
                      <img src={m.image} alt="Uploaded" className="max-w-full h-auto max-h-40 object-cover" />
                    </div>
                  )}
                  <div>{m.text}</div>
                  {/* Timestamp & Read Receipt */}
                  <div className="flex items-center justify-end gap-1 mt-1 select-none">
                     <span className="text-[9px] text-gray-400 font-medium">
                        {m.timestamp ? new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : ''}
                     </span>
                     <CheckCheck size={12} className="text-blue-500" />
                  </div>
               </div>
            )}

            {/* Model Message (Perplexity Style) */}
            {m.role === 'model' && (
              <div className="w-full space-y-3">

                 {/* 1. Sources Section */}
                 {m.sources && m.sources.length > 0 && (
                    <div className="mb-2">
                       <div className="flex items-center gap-2 mb-2">
                          <BrainCircuit size={14} className="text-blue-600 dark:text-blue-400" />
                          <span className="text-xs font-bold text-slate-900 dark:text-white uppercase tracking-wider">Sources</span>
                       </div>
                       <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                          {m.sources.map((src, idx) => (
                             <a 
                               key={idx} 
                               href={src.uri} 
                               target="_blank" 
                               rel="noopener noreferrer"
                               className="flex-shrink-0 w-36 p-2 bg-gray-50 dark:bg-slate-800 border border-gray-100 dark:border-slate-700 rounded-lg hover:border-blue-300 dark:hover:border-blue-500 transition-colors group flex flex-col justify-between h-20 relative overflow-hidden"
                             >
                                <p className="text-[10px] text-slate-500 dark:text-slate-400 line-clamp-2 leading-tight mb-1">{src.title}</p>
                                <div className="flex items-center gap-1.5 mt-auto">
                                   {isMapSource(src.uri) ? (
                                      <div className="w-4 h-4 rounded-full bg-green-100 dark:bg-green-900 flex items-center justify-center text-green-600">
                                         <MapPin size={10} />
                                      </div>
                                   ) : (
                                      <div className="w-4 h-4 rounded-full bg-gray-200 dark:bg-slate-600 flex items-center justify-center text-[8px] uppercase font-bold text-gray-500">
                                         {new URL(src.uri).hostname.charAt(0)}
                                      </div>
                                   )}
                                   <span className="text-[9px] text-gray-400 truncate max-w-[80px]">{new URL(src.uri).hostname.replace('www.', '')}</span>
                                </div>
                             </a>
                          ))}
                       </div>
                    </div>
                 )}

                 {/* 2. Answer Section */}
                 <div>
                    <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                       <ReactMarkdown>{m.text}</ReactMarkdown>
                    </div>
                    {/* Timestamp for AI */}
                    <div className="flex items-center gap-2 mt-2">
                        <span className="text-[9px] text-gray-400 font-medium">
                            AI • {m.timestamp ? new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : ''}
                        </span>
                    </div>
                 </div>

                 {/* 3. Related Questions */}
                 {m.relatedQuestions && m.relatedQuestions.length > 0 && (
                    <div className="pt-1">
                       <div className="flex items-center gap-2 mb-2">
                          <Sparkles size={14} className="text-orange-500" />
                          <span className="text-xs font-bold text-slate-900 dark:text-white uppercase tracking-wider">Related</span>
                       </div>
                       <div className="flex flex-col gap-2">
                          {m.relatedQuestions.map((q, idx) => (
                             <button 
                               key={idx} 
                               onClick={() => handleSend(q)}
                               className="flex items-center justify-between text-left p-3 rounded-xl bg-gray-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-slate-700 border border-gray-100 dark:border-slate-700 transition-colors group"
                             >
                                <span className="text-sm text-slate-700 dark:text-slate-300 group-hover:text-blue-700 dark:group-hover:text-blue-400">{q}</span>
                                <div className="w-6 h-6 rounded-full bg-white dark:bg-slate-600 flex items-center justify-center text-gray-400 group-hover:text-blue-600 transition-colors shadow-sm">
                                   <ArrowRight size={12} />
                                </div>
                             </button>
                          ))}
                       </div>
                    </div>
                 )}
              </div>
            )}
          </div>
        ))} 

        {/* Loading State - Subtle Typing Indicator */}
        {loading && (
          <div className="flex items-start gap-3 animate-fade-in mt-2 mb-4">
             <div className="w-8 h-8 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white shrink-0 shadow-sm">
                 <BrainCircuit size={16} className="animate-pulse" />
             </div>
             <div className="bg-gray-50 dark:bg-slate-800 px-4 py-3 rounded-2xl rounded-tl-none border border-gray-100 dark:border-slate-700 flex items-center gap-2">
                 <div className="flex space-x-1">
                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.15s' }}></div>
                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.3s' }}></div>
                 </div>
                 <span className="text-xs text-gray-500 font-medium">Thinking...</span>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Image Preview Area */}
      {selectedImage && (
        <div className="px-4 py-2 bg-gray-50 dark:bg-slate-800 border-t border-gray-200 dark:border-slate-700 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2">
             <div className="relative w-12 h-12 rounded-lg overflow-hidden border border-gray-300 dark:border-slate-600">
               <img src={selectedImage} alt="Preview" className="w-full h-full object-cover" />
             </div>
             <span className="text-xs text-gray-500">Image attached</span>
          </div>
          <button onClick={() => setSelectedImage(null)} className="p-1 text-gray-400 hover:text-red-500">
            <Trash2 size={16} />
          </button>
        </div>
      )}

      {/* Input Area */}
      <div className="p-3 bg-white dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800 shrink-0 relative">

        {/* Media Options Popover */}
        {showMediaOptions && (
           <div className="absolute bottom-16 left-3 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-gray-200 dark:border-slate-700 p-2 z-20 flex flex-col gap-1 w-40 animate-fade-in-up">
              <button onClick={startCamera} className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-lg text-sm text-gray-700 dark:text-gray-200 w-full text-left">
                 <Aperture size={18} className="text-blue-600" /> Take Photo
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-lg text-sm text-gray-700 dark:text-gray-200 w-full text-left">
                 <Upload size={18} className="text-emerald-600" /> Upload
              </button>
           </div>
        )}
        {showMediaOptions && <div className="fixed inset-0 z-10" onClick={() => setShowMediaOptions(false)} />}

        <div className="flex items-center gap-2 bg-gray-100 dark:bg-slate-800 rounded-3xl px-2 py-1.5 border border-transparent focus-within:border-blue-500/30 focus-within:bg-white dark:focus-within:bg-slate-900 transition-all shadow-sm">

          <button 
            onClick={() => setShowMediaOptions(!showMediaOptions)}
            className="p-2 text-gray-400 hover:text-blue-600 transition-colors rounded-full hover:bg-gray-200 dark:hover:bg-slate-700"
          >
            <Camera size={20} />
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImageSelect} 
            accept="image/*" 
            className="hidden" 
          />

          <input 
            value={input} 
            onChange={e => setInput(e.target.value)} 
            onKeyDown={e => e.key === 'Enter' && handleSend()} 
            onPaste={handlePaste}
            placeholder={isListening ? "Listening..." : "Ask about places... (Paste image supported)"}
            className="flex-1 bg-transparent text-sm text-slate-900 dark:text-white outline-none py-2 min-w-0 placeholder-gray-400" 
          />

          <button 
            onClick={handleVoiceInput} 
            className={`p-2 transition-colors rounded-full ${
              isListening 
                ? 'bg-red-100 text-red-600 animate-pulse' 
                : 'text-gray-400 hover:text-blue-600 hover:bg-gray-200 dark:hover:bg-slate-700'
            }`}
          >
            <Mic size={20} />
          </button>

          <button 
            onClick={() => handleSend()} 
            disabled={loading || (!input.trim() && !selectedImage)} 
            className="bg-blue-600 hover:bg-blue-700 text-white p-2 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
    <SettingsModal isOpen={showSettings} onClose={() => setShowSettings(false)} type="privacy" />
    </>
  );
};
